// ---- compile-time probes (never executed; tsc is the assertion) ----
async function typeProbes(): Promise<void> {
  // A required request body keeps the options argument in the signature and
  // makes `body` mandatory inside it.
  F.postAcl({ body: PROBE });
  // @ts-expect-error the options argument is required when the body is
  F.postAcl();
  // @ts-expect-error body is required
  F.postAcl({});
  // An optional body means Opt<T> collapses the options argument away entirely.
  F.postAssetsReindex();
  F.postAssetsReindex({ body: PROBE });
  // A bodyless, parameterless alias takes nothing at all...
  F.getAclTemplates();
  // @ts-expect-error ...and never a `path`: the alias owns it (Omit<..., 'path'>)
  F.getAclTemplates({ path: {} });
  // Positionals are typed and counted.
  F.deleteAclTemplate('id');
  // @ts-expect-error missing positional
  F.deleteAclTemplate();
  // @ts-expect-error a string path parameter is not a number
  F.deleteAclTemplate(1);
  // @ts-expect-error one positional, not two
  F.deleteAclTemplate('id', 'extra');
}
void typeProbes;

const AUTH: ReadonlyArray<readonly [string, string]> = [
  ['App-ID', APP_ID],
  ['Auth-Token', AUTH_TOKEN],
];

const run = async (): Promise<void> => {
  const fails: string[] = [];
  const named = new Set(cases.map((c) => c.cmd));
  let bindings = 0;
  let bodies = 0;
  let noAuth = 0;
  for (const c of cases) {
    seen.length = 0;
    try {
      await c.call();
    } catch (e) {
      // response decoding is out of scope; the request is already captured
    }
    if (seen.length !== 1) {
      fails.push(`${c.cmd}: ${seen.length} requests reached fetch, want 1`);
      continue;
    }
    const req = seen[0]!;
    const url = new URL(req.url);
    bindings += c.query.length + c.headers.length;
    if (req.method !== c.method) {
      fails.push(`${c.cmd}: method ${req.method}, want ${c.method}`);
    }
    if (url.pathname !== c.path) {
      fails.push(`${c.cmd}: path ${url.pathname}, want ${c.path}`);
    }
    const got = [...url.searchParams.keys()];
    if (got.length !== c.query.length) {
      fails.push(`${c.cmd}: ${got.length} query parameters [${got}], want ${c.query.length}`);
    }
    for (const [k, v] of c.query) {
      // an empty key means an object-typed parameter, which the client explodes
      // into keys of its own: assert the value reached the query, not its key
      const g = k === '' ? (url.search.includes(v) ? v : null) : url.searchParams.get(k);
      if (g !== v) {
        fails.push(`${c.cmd}: query ${k || '(exploded)'}=${g}, want ${v}`);
      }
    }
    for (const [k, v] of c.headers) {
      if (req.headers.get(k) !== v) {
        fails.push(`${c.cmd}: header ${k}=${req.headers.get(k)}, want ${v}`);
      }
    }
    if (c.auth.length === 0) {
      noAuth++;
    }
    for (const [k, v] of AUTH) {
      const want = c.auth.includes(k) ? v : null;
      if (req.headers.get(k) !== want) {
        fails.push(`${c.cmd}: auth header ${k}=${req.headers.get(k)}, want ${want}`);
      }
    }
    if (c.body) {
      bodies++;
      const text = await req.text();
      if (!text.includes(MARKER)) {
        fails.push(`${c.cmd}: body never reached the wire (${text.slice(0, 120)})`);
      }
    }
  }
  for (const name of Object.keys(F)) {
    if (!named.has(name)) {
      fails.push(`${name}: exported by friendly.ts with no names.json row`);
    }
  }
  // only failures attributable to a case may lower the per-alias count; the rest
  // are suite-level and reported separately, so neither number can flatter itself
  const heads = fails.map((f) => f.split(':')[0] ?? '');
  const bad = new Set(heads.filter((h) => named.has(h)));
  const suite = heads.filter((h) => !named.has(h)).length;
  console.log(
    `${cases.length - bad.size}/${cases.length} ` +
      `friendly aliases verified on the wire (${bindings} query+header bindings ` +
      `exercised, ${bodies} request bodies, ${noAuth} unauthenticated ops)` +
      (suite ? `; ${suite} suite-level failure(s)` : ''),
  );
  if (fails.length) {
    throw new Error(fails.slice(0, 60).map((f) => `FAIL ${f}`).join('\n'));
  }
};

configure({ appId: APP_ID, authToken: AUTH_TOKEN });
for (const c of clients) {
  c.setConfig({ fetch: capture });
}
declare const process: { exit(code: number): void };
run().catch((e) => { console.error(e); process.exit(1); });
